const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Great Plains grasslands region (Kansas, Nebraska, South Dakota, North Dakota)
  const greatPlains = ee.Geometry.Rectangle([-104.0, 37.0, -96.0, 49.0]);

  // 2. Get CDL data for 2003 and 2019
  const cdl2003 = ee.ImageCollection('USDA/NASS/CDL')
    .filter(ee.Filter.date('2003-01-01', '2003-12-31'))
    .first()
    .select('cropland');

  const cdl2019 = ee.ImageCollection('USDA/NASS/CDL')
    .filter(ee.Filter.date('2019-01-01', '2019-12-31'))
    .first()
    .select('cropland');

  // 3. Check if images exist
  const col2003 = ee.ImageCollection('USDA/NASS/CDL')
    .filter(ee.Filter.date('2003-01-01', '2003-12-31'));
  const col2019 = ee.ImageCollection('USDA/NASS/CDL')
    .filter(ee.Filter.date('2019-01-01', '2019-12-31'));

  const size2003 = col2003.size().getInfo();
  const size2019 = col2019.size().getInfo();

  if (size2003 === 0 || size2019 === 0) {
    console.log(`2003 Images: ${size2003}, 2019 Images: ${size2019}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Create masks for crops: Corn (1), Soybeans (5), Winter Wheat (24), Spring Wheat (23), Durum Wheat (22)
  const cropMask2003 = cdl2003.eq(1).or(cdl2003.eq(5)).or(cdl2003.eq(24)).or(cdl2003.eq(23)).or(cdl2003.eq(22));
  const cropMask2019 = cdl2019.eq(1).or(cdl2019.eq(5)).or(cdl2019.eq(24)).or(cdl2019.eq(23)).or(cdl2019.eq(22));

  // 5. Calculate pixel counts (30m resolution, so each pixel = 900 m²)
  const count2003 = cropMask2003.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: greatPlains,
    scale: 3000,
    maxPixels: 1e9
  }).get('cropland').getInfo();

  const count2019 = cropMask2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: greatPlains,
    scale: 3000,
    maxPixels: 1e9
  }).get('cropland').getInfo();

  console.log(`2003 Crop Pixels: ${count2003}`);
  console.log(`2019 Crop Pixels: ${count2019}`);

  // 6. Validation
  if (count2003 === null || count2019 === null || count2003 === undefined || count2019 === undefined) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (count2003 === 0 && count2019 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 7. Calculate area in km²
  const area2003_km2 = (count2003 * 9000000) / 1e6; // 3000m scale = 9M m² per pixel
  const area2019_km2 = (count2019 * 9000000) / 1e6;

  console.log(`2003 Area: ${area2003_km2.toFixed(0)} km²`);
  console.log(`2019 Area: ${area2019_km2.toFixed(0)} km²`);
  console.log(`Change: ${((area2019_km2 - area2003_km2) / area2003_km2 * 100).toFixed(1)}%`);

  // 8. Final answer
  if (count2019 > count2003) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
